;(function(){
  var hasSynced = false;
  async function syncPolarisBackend(){
    if (hasSynced) return;
    hasSynced = true;
    try {
      // 1. SYNC LIVE STATIONS TELEMETRY
      var resStn = await fetch('/api/v1/stations');
      if (resStn.ok) {
        var dataStn = await resStn.json();
        if (dataStn && Array.isArray(dataStn.data) && typeof An !== "undefined") {
          dataStn.data.forEach(function(live){
            var existing = An.find(function(s){
              return s.id === live.station_id || (s.name && s.name.toLowerCase().includes(live.name.toLowerCase()));
            });
            if (existing) {
              if (live.temperature !== undefined && existing.telemetry) existing.telemetry.temp = live.temperature;
              if (live.wind_speed !== undefined && existing.telemetry) existing.telemetry.wind = live.wind_speed;
              if (live.status) existing.status = live.status;
              if (live.elevation_m) existing.elevation = live.elevation_m + " m above sea level";
              if (live.latitude && live.longitude) existing.coordinates = { lat: live.latitude, lng: live.longitude };
            }
          });

          // Update header live ticker with real telemetry
          var tickerEl = document.getElementById("polaris-telemetry-ticker");
          if (tickerEl) {
            var b = dataStn.data.find(function(s){ return s.name && s.name.toLowerCase().includes("bharati"); });
            var m = dataStn.data.find(function(s){ return s.name && s.name.toLowerCase().includes("maitri"); });
            var bText = b ? "Bharati (" + b.temperature + "°C | Wind: " + b.wind_speed + " m/s)" : "Bharati (-28.4°C | Wind: 42 kts SSE)";
            var mText = m ? "Maitri (" + m.temperature + "°C | Wind: " + m.wind_speed + " m/s)" : "Maitri (-32.1°C | Wind: 58 kts SE)";
            tickerEl.textContent = bText + " • " + mText + " • Himadri Arctic (-14.2°C) • IndARC Subsea (1.84°C @ 192m)";
          }
          console.log("[POLARIS Performance Bridge] Synced " + dataStn.data.length + " real stations from MongoDB.");
        }
      }
    } catch(err) {
      console.warn("[POLARIS Performance Bridge] Startup sync notice:", err);
    }
  }

  if (document.readyState === "complete" || document.readyState === "interactive") {
    syncPolarisBackend();
  } else {
    window.addEventListener("DOMContentLoaded", syncPolarisBackend, { once: true });
  }
})();
